"use strict";(globalThis.webpackChunk_8x8_developer_docs=globalThis.webpackChunk_8x8_developer_docs||[]).push([[90324],{98546:e=>{e.exports=JSON.parse('{"id":"2026-08-04-templateid-in-direct-send-delivery-receipts","date":"2026-08-04","products":["Connect"],"product":"Connect","channel":"WhatsApp","changeType":"Added","title":"templateId in Direct Send delivery receipts","excerpt":"WhatsApp delivery receipts now include a templateId field for messages sent via the WhatsApp Direct Send API, so you can correlate a receipt back to the exact template that was delivered.","hasArticle":true,"bodyHtml":"<p>WhatsApp delivery receipts now include a <strong><code>templateId</code></strong> field for messages sent via the WhatsApp Direct Send API, so you can correlate a receipt back to the exact template that was delivered.</p>\\n<p><code>templateId</code> (string) is the template ID WhatsApp used to deliver the message. It appears inside the <code>whatsapp</code> object of the delivery receipt and is <strong>only present for messages sent through the Direct Send API</strong>:</p>\\n<pre><code class=\\"language-json\\">&quot;whatsapp&quot;: {\\n  &quot;pricingCategory&quot;: &quot;marketing&quot;,\\n  &quot;templateId&quot;: &quot;1281032340757288&quot;\\n}\\n</code></pre>\\n<p>The field is documented in the WhatsApp object table alongside <code>providerErrorCode</code> and <code>pricingCategory</code>, and shown in the delivery-receipt examples (template with image header and buttons, interactive list message, and so on).</p>\\n<p>See <a href=\\"/connect/docs/delivery-receipts-for-outbound-chatapps\\">Delivery receipts for outbound Chat Apps</a>.</p>\\n"}')}}]);